  // ---------- Desktop / OS notifications ----------
  // מחזיר את התראות המערכת לצ׳אט אינווסט ולתזכורות גם כשהמשתמש נמצא בחלון אחר.
  const DesktopNotifications = {
    icon: "./icon-192.png",
    lastSent: new Map(),
    ready(){
      return typeof window !== "undefined" && "Notification" in window;
    },
    permission(){
      if(!this.ready()) return "unsupported";
      return Notification.permission || "default";
    },
    async ensurePermission(){
      try {
        if(!this.ready()) return "unsupported";
        if(Notification.permission === "granted") return "granted";
        if(Notification.permission === "denied") return "denied";
        if(typeof Notification.requestPermission !== "function") return Notification.permission || "default";
        const result = await Notification.requestPermission();
        return result || Notification.permission || "default";
      } catch(_e){
        return this.permission();
      }
    },
    shouldSkip(tag, body){
      const key = `${safeTrim(tag) || "general"}::${safeTrim(body).slice(0, 120)}`;
      const now = Date.now();
      const prev = Number(this.lastSent.get(key) || 0);
      this.lastSent.set(key, now);
      if(this.lastSent.size > 80){
        const cutoff = now - 120000;
        Array.from(this.lastSent.entries()).forEach(([k, ts]) => { if(Number(ts || 0) < cutoff) this.lastSent.delete(k); });
      }
      return prev && (now - prev) < 2500;
    },
    async notify(title, options = {}){
      try {
        if(!this.ready()) return false;
        const cleanTitle = safeTrim(title) || "GEMEL INVEST";
        const cleanBody = safeTrim(options.body || options.text || "");
        const tag = safeTrim(options.tag) || (`gi-${Date.now()}`);
        if(this.shouldSkip(tag, cleanBody)) return false;

        let permission = this.permission();
        if(permission === "default") permission = await this.ensurePermission();
        if(permission !== "granted") return false;

        const notification = new Notification(cleanTitle, {
          body: cleanBody,
          icon: options.icon || this.icon,
          badge: options.badge || this.icon,
          tag,
          dir: "rtl",
          lang: "he",
          requireInteraction: !!options.requireInteraction,
          silent: !!options.silent
        });

        notification.onclick = () => {
          try { window.focus(); } catch(_e) {}
          try { notification.close(); } catch(_e) {}
          try { if(typeof options.onClick === "function") options.onClick(); } catch(_e) {}
        };
        return true;
      } catch(err){
        try { console.warn("[DesktopNotifications] notify failed", err); } catch(_e) {}
        return false;
      }
    }
  };
  try { window.GIDesktopNotifications = DesktopNotifications; } catch(_e) {}

  function _playGiMarimbaNote(ctx, dest, freq, start, duration, velocity){
    const t = ctx.currentTime + start;
    const partials = [
      { mult: 1,    amp: 1.0 },
      { mult: 2,    amp: 0.45 },
      { mult: 3,    amp: 0.2 },
      { mult: 4.22, amp: 0.08 },
    ];
    partials.forEach(({ mult, amp }) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(freq * mult, t);
      if(mult === 1){
        osc.frequency.exponentialRampToValueAtTime(freq * 0.996, t + 0.03);
      }
      const peak = velocity * amp;
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(Math.max(peak, 0.0002), t + 0.003);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
      osc.connect(gain);
      gain.connect(dest);
      osc.start(t);
      osc.stop(t + duration + 0.1);
    });
  }

  function playGiNotifySound(){
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if(!Ctx) return;
      if(!playGiNotifySound._ctx) playGiNotifySound._ctx = new Ctx();
      const ctx = playGiNotifySound._ctx;
      if(ctx.state === "suspended"){
        try { void ctx.resume(); } catch(_e) {}
      }
      if(!playGiNotifySound._master){
        const master = ctx.createGain();
        master.gain.value = 0.9;
        const comp = ctx.createDynamicsCompressor();
        comp.threshold.value = -20;
        comp.knee.value = 8;
        comp.ratio.value = 3;
        comp.attack.value = 0.003;
        comp.release.value = 0.12;
        master.connect(comp);
        comp.connect(ctx.destination);
        playGiNotifySound._master = master;
      }
      const master = playGiNotifySound._master;
      const N = {
        E: 1318.51,
        G: 1567.98,
        A: 1760.00,
        B: 1975.53,
        C: 2093.00,
      };
      const seq = "E G A B C B A G E G A B C B A G".split(" ");
      const step = 0.112;
      const noteDur = 0.22;
      seq.forEach((key, i) => {
        const vel = i === seq.length - 1 ? 0.2 : 0.17;
        const dur = i === seq.length - 1 ? 0.32 : noteDur;
        _playGiMarimbaNote(ctx, master, N[key], i * step, dur, vel);
      });
    } catch(_e) {}
  }

