  try {
    window.__GI_SUPABASE_CONFIG = {
      url: SUPABASE_URL,
      publishableKey: SUPABASE_PUBLISHABLE_KEY,
      metaTable: SUPABASE_TABLES.meta
    };
  } catch(_e) {}

  function getMirrorAssign(rec){
    try{
      const m = rec?.payload?.mirrorFlow?.mirrorAssign;
      if(!m || typeof m !== "object") return null;
      const agentId = safeTrim(m.agentId);
      const agentName = safeTrim(m.agentName);
      if(!agentId && !agentName) return null;
      return { agentId, agentName, assignedBy: safeTrim(m.assignedBy), assignedAt: safeTrim(m.assignedAt) };
    }catch(_e){ return null; }
  }
  function setMirrorAssign(rec, agent, byName){
    if(!rec) return;
    if(!rec.payload || typeof rec.payload !== "object") rec.payload = {};
    if(!rec.payload.mirrorFlow || typeof rec.payload.mirrorFlow !== "object") rec.payload.mirrorFlow = {};
    rec.payload.mirrorFlow.mirrorAssign = {
      agentId: safeTrim(agent?.id),
      agentName: safeTrim(agent?.name || agent?.username),
      assignedBy: safeTrim(byName),
      assignedAt: nowISO()
    };
  }
  function clearMirrorAssign(rec){
    try{
      if(!rec?.payload?.mirrorFlow || typeof rec.payload.mirrorFlow !== "object") return;
      rec.payload.mirrorFlow.mirrorAssign = null;
    }catch(_e){}
  }
  function currentUserMatchesMirrorAssign(assign){
    if(!assign) return false;
    const meId = safeTrim(Auth?.current?.id);
    const meName = safeTrim(Auth?.current?.name);
    const assignId = safeTrim(assign.agentId);
    const assignName = safeTrim(assign.agentName);
    if(meId && assignId && meId === assignId) return true;
    if(meName && assignName && meName === assignName) return true;
    try{
      const agents = State.data?.agents || [];
      const ag = assignId ? agents.find((a) => safeTrim(a?.id) === assignId) : null;
      if(ag){
        if(meId && safeTrim(ag.id) === meId) return true;
        if(meName && (safeTrim(ag.name) === meName || safeTrim(ag.username) === meName)) return true;
      }
      if(meId){
        const me = agents.find((a) => safeTrim(a?.id) === meId);
        if(me && assignName && (safeTrim(me.name) === assignName || safeTrim(me.username) === assignName)) return true;
      }
    }catch(_e){}
    return false;
  }

